import { Question } from '../types';

export const NISM_CH8_DATA: Question[] = [
  { id: 8001, sec: "8.1 Financial Statements", q: "In India, the list of financial statements and the format that listed companies must maintain and publish are governed by:", opts: ["Schedule III of the Companies Act 2013 and IndAS 1", "Schedule I of the Companies Act 2013 and IndAS 16", "Ind AS 110 alone", "Schedule III of the Companies Act 2013 and Ind AS 16 only"], ans: 0, exp: "Schedule III of the Companies Act 2013 and IndAS 1 govern the list and format of financial statements. Ind AS 110 deals with consolidation; Ind AS 16 with PPE." },
  { id: 8002, sec: "8.1 Financial Statements", q: "Which of the following is NOT part of the complete set of financial statements listed by IndAS 1 in the chapter?", opts: ["Statement of changes in shareholder's equity", "Independent valuation report of the company's brand", "Cash flow statement", "Statement of profit and loss (including OCI)"], ans: 1, exp: "The set comprises balance sheet, P&L (with OCI), statement of changes in equity, cash flow statement and detailed notes. A brand valuation report is not part of it." },
  { id: 8003, sec: "8.1 Financial Statements", q: "Other comprehensive income (OCI) includes:", opts: ["only dividends received from subsidiaries", "the company's share capital movements", "certain gains or losses on changes in fair value of assets and liabilities that are required/permitted not to be recognised as part of income and expense", "all operating expenses incurred during the year"], ans: 2, exp: "OCI covers certain gains/losses due to fair-value changes not recognised as part of income and expense in P&L." },
  { id: 8004, sec: "8.1 Financial Statements", q: "While presenting financial information, a company must provide comparable information for at least:", opts: ["three prior periods", "five prior periods", "no prior period if it is a listed company", "one prior period"], ans: 3, exp: "Every statement must show current and at least one prior period. Companies may provide longer comparatives if they prefer." },
  { id: 8005, sec: "8.1 Financial Statements", q: "Which statement provides information on assets, liabilities and equity at the END of the financial reporting period?", opts: ["Balance sheet (Statement of Financial Position)", "Profit and loss account", "Cash flow statement", "Statement of other comprehensive income only"], ans: 0, exp: "The balance sheet is a position statement as at a date; P&L shows performance over a period; cash flow shows sources and uses of cash." },
  { id: 8006, sec: "8.2 Consolidation & Control", q: "According to the chapter, a company controls another company when it:", opts: ["owns exactly 50% of the paid-up capital", "owns more than 50% of voting rights or has the right to appoint the majority of the board of directors", "has lent money to the other company", "supplies more than half of its raw materials"], ans: 1, exp: "Control arises from >50% voting rights or the right to appoint a majority of the board. The controlled company is the subsidiary." },
  { id: 8007, sec: "8.2 Consolidation & Control", q: "Which of the following statements about a holding company is INCORRECT?", opts: ["It can be de-facto controlling a subsidiary through power over strategy and operations", "In such de-facto control cases it must present consolidated statements as per Ind AS 110", "It must necessarily hold more than 50% ownership in the subsidiary to present consolidated statements", "The controlled company is referred to as a subsidiary"], ans: 2, exp: "It is not necessary for the holding company to have >50% ownership; power to control strategy and operations (de-facto control) suffices." },
  { id: 8008, sec: "8.2 Consolidation & Control", q: "Toyota Motor Corporation (Japan) operates through subsidiaries worldwide. Its stand-alone financial statement will show:", opts: ["group sales across China, India and North America", "only sales in India", "sales of subsidiaries but not of the parent", "only the sales of the Japanese entity itself, not of its subsidiaries elsewhere"], ans: 3, exp: "Stand-alone statements reflect only the independent entity; group-wide sales appear in the consolidated statement." },
  { id: 8009, sec: "8.2 Consolidation & Control", q: "From an equity-analysis perspective, which statements are generally preferred and why?", opts: ["Consolidated statements, because they give a more holistic picture of group performance", "Stand-alone statements, because they include subsidiaries' revenues", "Stand-alone statements, because they are audited more strictly", "Quarterly statements only, because they are mandatory"], ans: 0, exp: "Consolidated statements are generally preferred over stand-alone for a holistic picture of group performance." },
  { id: 8010, sec: "8.2 Consolidation & Control", q: "Stand-alone analysis of a parent company becomes particularly important when:", opts: ["the parent owns 100% of all subsidiaries", "a subsidiary cannot pay dividends because of strict capital controls or a debt covenant", "the subsidiary is listed on an exchange", "the subsidiary is a banking company"], ans: 1, exp: "If dividends cannot flow up (due to capital controls or debt covenants), analysts must check whether the parent can fend for itself in times of crisis." },
  { id: 8011, sec: "8.2 Consolidation & Control", q: "As per SEBI regulations discussed in the chapter, listed companies must publish:", opts: ["consolidated results quarterly and stand-alone annually", "only consolidated results, both quarterly and annually", "consolidated financial statements annually and stand-alone results quarterly", "only stand-alone results, annually"], ans: 2, exp: "Consolidated annual and stand-alone quarterly are mandatory; consolidated quarterly is voluntary for some companies." },
  { id: 8012, sec: "8.2 Consolidation & Control", q: "Equity analysts find it challenging to analyse groups that do not publish consolidated quarterly numbers because:", opts: ["such groups are not required to publish annual reports", "stand-alone numbers are always misleading", "quarterly numbers are always unaudited", "the gap between two annual reports is almost a year, leaving dated information"], ans: 3, exp: "Without consolidated quarterly numbers, analysts rely on dated annual information." },
  { id: 8013, sec: "8.3 Balance Sheet Items", q: "Which types of companies follow a different balance-sheet format prescribed by their regulators rather than the Companies Act format?", opts: ["Banking, insurance and utility companies", "Manufacturing, retail and IT companies", "Only unlisted companies", "Only companies with subsidiaries"], ans: 0, exp: "Companies Act format applies to all industries except those with separate regulator requirements: banking, insurance and utility companies." },
  { id: 8014, sec: "8.3 Balance Sheet Items", q: "Under generally accepted accounting principles, which of the following can NOT be recognised as an asset in the balance sheet?", opts: ["Internally developed software programs", "A self-generated brand name", "Acquired patents", "Goodwill arising from an acquisition"], ans: 1, exp: "Self-generated assets such as own brand name cannot be shown; however internally developed software can be recognised, and acquired patents/goodwill are recognized." },
  { id: 8015, sec: "8.3 Balance Sheet Items", q: "Which of the following describes a current asset?", opts: ["An asset that gives benefit for more than ten years", "Any asset purchased in cash", "An asset likely to benefit the organisation within one operating cycle", "Only cash held in a bank account"], ans: 2, exp: "Current assets are expected to benefit within one operating cycle, typically taken as one year or less." },
  { id: 8016, sec: "8.3 Balance Sheet Items", q: "Property, Plant and Equipment (PPE) is normally shown in the balance sheet at:", opts: ["current market price", "replacement cost", "face value", "historical cost net of accumulated depreciation"], ans: 3, exp: "PPE is shown at historical cost net of accumulated depreciation, unless the revaluation model is adopted." },
  { id: 8017, sec: "8.3 Balance Sheet Items", q: "A company opts for the revaluation model for PPE under IndAS 16. Which statement is correct?", opts: ["The choice must be applied to the entire asset class", "It can be applied to any single asset selectively", "Revaluation is not permitted under IndAS 16", "Revalued amounts are shown only in the notes"], ans: 0, exp: "The revaluation choice under IndAS 16 must be applied to an entire asset class, not selectively." },
  { id: 8018, sec: "8.3 Balance Sheet Items", q: "Capital work in progress represents:", opts: ["Intangible assets not yet ready", "PPE currently under construction and not ready for operation", "Work-in-progress inventory in factories", "Advance given to suppliers"], ans: 1, exp: "CWIP represents PPE under construction; once completed and ready for use, it is transferred to PPE." },
  { id: 8019, sec: "8.3 Balance Sheet Items", q: "Company A acquires 100% of Company B for Rs.500 crore. The fair value of B's net assets (assets minus liabilities) is Rs.420 crore. The goodwill recognised is:", opts: ["Rs.420 crore", "Rs.500 crore", "Rs.80 crore", "Rs.920 crore"], ans: 2, exp: "Goodwill = Consideration paid - fair value of net assets = 500 - 420 = Rs.80 crore." },
  { id: 8020, sec: "8.3 Balance Sheet Items", q: "In FY2018 Bharti Airtel paid Rs.3,200 crore for 100% of Tigo Rwanda whose fair value of net assets was Rs.2,838 crore. The balance was recognised as:", opts: ["capital reserve of Rs.362 crore", "goodwill of Rs.3,200 crore", "a provision of Rs.362 crore", "goodwill of Rs.362 crore"], ans: 3, exp: "3,200 - 2,838 = 362 crore excess consideration recognized as Goodwill." },
  { id: 8021, sec: "8.3 Balance Sheet Items", q: "If a company pays an amount LOWER than the fair value of the net assets taken over, the difference is:", opts: ["taken to capital reserves under equity", "recognised as goodwill", "expensed as exceptional item in P&L", "shown as deferred revenue"], ans: 0, exp: "The shortfall is credited to capital reserves under equity on the balance sheet." },
  { id: 8022, sec: "8.3 Balance Sheet Items", q: "Goodwill is written off as impairment when:", opts: ["the acquired company reports a profit", "its value in use is lower than its carrying value", "the share price of the acquirer rises", "it has been held for more than five years"], ans: 1, exp: "Goodwill is periodically tested for impairment; if value in use is lower than carrying value, it is written off." },
  { id: 8023, sec: "8.3 Balance Sheet Items", q: "Intangible assets are generally:", opts: ["physical assets shown at market value", "always self-generated brand names", "in the form of a legal right, shown at cost minus accumulated amortisation", "not permitted in the balance sheet"], ans: 2, exp: "Intangible assets (copyrights, patents, licenses) are shown at cost less accumulated amortization." },
  { id: 8024, sec: "8.3 Balance Sheet Items", q: "Investments in joint ventures / associates (companies not controlled) are reported under:", opts: ["the consolidation method", "fair value through P&L only", "historical cost with no later adjustment", "the equity method"], ans: 3, exp: "Associates and joint ventures where the entity has significant influence but not control are reported using the equity method." },
  { id: 8025, sec: "8.3 Balance Sheet Items", q: "Under the equity method, the carrying amount of an investment in an associate is:", opts: ["adjusted for the investor's share of profit or loss and OCI, and reduced by dividends received", "increased by dividends received", "unchanged until the investment is sold", "adjusted only for the investor's own profit"], ans: 0, exp: "Carrying amount increases/decreases by the investor's share of net profit/OCI, and is reduced by dividends received." },
  { id: 8026, sec: "8.3 Balance Sheet Items", q: "Inventory in the balance sheet is shown at:", opts: ["cost price or market value, whichever is higher", "cost price or market value, whichever is lower", "market value only", "selling price less profit margin"], ans: 1, exp: "Valued at lower of cost or net realizable value (market value)." },
  { id: 8027, sec: "8.3 Balance Sheet Items", q: "Which of the following is shown net of provision for doubtful debts?", opts: ["Inventory", "Short-term investments", "Receivables", "Cash equivalents"], ans: 2, exp: "Trade receivables represent dues from customers and are presented net of allowance for doubtful debts." },
  { id: 8028, sec: "8.3 Balance Sheet Items", q: "'Cash and cash equivalents' in the chapter includes:", opts: ["only physical cash", "all bank accounts including long-term deposits", "receivables due within one year", "cash, balances in current accounts, short-term bank deposits and money market investments"], ans: 3, exp: "Includes cash, current account balances, short-term deposits, and highly liquid money-market holdings." },
  { id: 8029, sec: "8.3 Balance Sheet Items", q: "Equity in the balance sheet represents:", opts: ["the residual interest of owners, i.e. assets minus liabilities", "total liabilities of the company", "the market capitalisation", "current assets minus current liabilities"], ans: 0, exp: "Equity is the residual interest in the assets of the company after deducting all its liabilities." },
  { id: 8030, sec: "8.3 Balance Sheet Items", q: "Share premium refers to:", opts: ["the face value of paid-up capital", "the amount received in an IPO or FPO over and above the face value of shares", "profit not distributed as dividend", "surplus from revaluation of assets"], ans: 1, exp: "Share premium (securities premium) is the excess over face value collected during share issuances." },
  { id: 8031, sec: "8.3 Balance Sheet Items", q: "Which of the following equity components is typically NOT available for distribution as dividend?", opts: ["Retained earnings", "General reserve", "Capital reserve and revaluation reserve", "None; all equity components can be distributed"], ans: 2, exp: "Capital reserves and revaluation reserves are non-distributable surpluses." },
  { id: 8032, sec: "8.3 Balance Sheet Items", q: "Minority (non-controlling) interest represents:", opts: ["the parent's share in associates", "preference share capital of the parent", "dues payable to minority suppliers", "the share of equity of a subsidiary belonging to shareholders other than the parent"], ans: 3, exp: "NCI reflects the equity in a consolidated subsidiary not attributable directly or indirectly to the parent." },
  { id: 8033, sec: "8.3 Balance Sheet Items", q: "Retained earnings refers to:", opts: ["profit and OCI earned that has not been distributed as dividend or set aside for another specific purpose", "profit paid as dividend", "amount raised in an IPO", "accumulated depreciation"], ans: 0, exp: "Accumulated profits retained in the business rather than paid out as dividends." },
  { id: 8034, sec: "8.3 Balance Sheet Items", q: "Non-current liabilities are obligations to be fulfilled:", opts: ["within one operating cycle", "after one year", "only on liquidation", "within three months"], ans: 1, exp: "Obligations due beyond 12 months or one operating cycle." },
  { id: 8035, sec: "8.3 Balance Sheet Items", q: "In the balance sheet, the portion of long-term debt falling due within one year is:", opts: ["ignored until it is repaid", "added to equity", "shown separately as current portion of long-term debt, usually under current liabilities", "shown as a provision"], ans: 2, exp: "Shown as 'current maturities of long-term debt' under current liabilities." },
  { id: 8036, sec: "8.3 Balance Sheet Items", q: "A lease liability is recognised when a company acquires the right to use an asset under a lease agreement for a period:", opts: ["of less than one month", "of any duration whatsoever, even a day", "only if the lessor is a bank", "of more than one year"], ans: 3, exp: "Recognized under IndAS 116 for leases exceeding 12 months." },
  { id: 8037, sec: "8.3 Balance Sheet Items", q: "On the liability side, derivative instruments represent:", opts: ["mark-to-market losses on derivative contracts", "mark-to-market gains on derivative contracts", "equity shares to be issued", "dividend payable"], ans: 0, exp: "Mark-to-market negative values (losses) on outstanding derivative contracts." },
  { id: 8038, sec: "8.3 Balance Sheet Items", q: "A customer pays Rs.1,200 for a 6-month prepaid pack. After one month, how much remains as deferred revenue, and how is it classified?", opts: ["Rs.200, a non-current liability", "Rs.1,000, a current liability", "Rs.1,200, a non-current liability", "Rs.1,000, a non-current asset"], ans: 1, exp: "1 month recognized (Rs.200). Remaining 5 months = Rs.1,000 to be delivered within 5 months, hence a current liability." },
  { id: 8039, sec: "8.3 Balance Sheet Items", q: "Which statement about provisions is correct per the chapter?", opts: ["Provisions are set aside for unknown purposes", "Provisions are part of equity", "Provisions are set aside for a specific obligation which is yet to be fully quantified", "Provisions are never shown on the balance sheet"], ans: 2, exp: "A provision is a liability of uncertain timing or amount, set aside for a specific obligation." },
  { id: 8040, sec: "8.3 Balance Sheet Items", q: "Which item is classified under current liabilities?", opts: ["Long-term borrowings due after two years", "Goodwill", "Share premium", "Advances from customers"], ans: 3, exp: "Customer advances are obligations to deliver goods/services within the short term." },
  { id: 8041, sec: "8.3 Balance Sheet Items", q: "Short-term debt is best described as:", opts: ["borrowing for less than one year, often rolled over or refinanced in practice", "debt that can never be rolled over", "debt payable to suppliers of goods", "equity-like funds from promoters"], ans: 0, exp: "Borrowings due within 1 year, often continuously rolled over in practice." },
  { id: 8042, sec: "8.3 Balance Sheet Items", q: "Which of the following is NOT included in 'total debt' as computed by analysts in the chapter?", opts: ["Long-term debt", "Trade payables", "Current portion of long-term debt", "Short-term debt"], ans: 1, exp: "Trade payables are non-interest-bearing operating liabilities, not financial debt." },
  { id: 8043, sec: "8.3 Balance Sheet Items", q: "Net working capital under the accountant's approach is:", opts: ["current liabilities minus current assets", "inventory plus receivables minus payables", "current assets minus current liabilities", "total assets minus total liabilities"], ans: 2, exp: "NWC = Current Assets - Current Liabilities." },
  { id: 8044, sec: "8.3 Balance Sheet Items", q: "A company has inventory Rs.200, trade receivables Rs.500, trade payables Rs.350, cash Rs.100 and short-term investments Rs.80. Its core working capital is:", opts: ["Rs.330", "Rs.1,230", "Rs.430", "Rs.350"], ans: 3, exp: "Core Working Capital = Inventory + Trade Receivables - Trade Payables = 200 + 500 - 350 = Rs.350." },
  { id: 8045, sec: "8.3 Balance Sheet Items", q: "Why do analysts compute core working capital instead of simply current assets minus current liabilities?", opts: ["Current assets may include short-term investments and current liabilities include items such as current maturities of long-term debt that do not arise from day-to-day operations", "Because net working capital is always negative", "Because accounting standards prohibit net working capital", "Because core working capital includes cash and borrowings"], ans: 0, exp: "Core WC filters out surplus cash, liquid investments, and short-term financing debt to focus purely on operating items." },
  { id: 8046, sec: "8.3 Balance Sheet Items", q: "The term 'working capital' is described as a misnomer when taken to mean capital locked up for day-to-day requirements, because:", opts: ["working capital is always zero", "a company does not keep safety stock or give customer credit merely for day-to-day needs; it needs funds because it spends first and customers pay later", "working capital refers only to fixed assets", "companies never need to finance receivables"], ans: 1, exp: "The cash conversion cycle forces the firm to fund production, storage, and credit before cash arrives." },
  { id: 8047, sec: "8.4 P&L Analysis", q: "IndAS 1 requires that the profit and loss statement mandatorily include:", opts: ["cash flow from operations", "balance sheet ratios", "other comprehensive income", "the audit report"], ans: 2, exp: "P&L under IndAS 1 must include Statement of Profit and Loss and Other Comprehensive Income (OCI)." },
  { id: 8048, sec: "8.4 P&L Analysis", q: "Other income in a P&L typically includes:", opts: ["sales of goods to customers", "cost of raw materials", "employee benefits", "income from investments or profit on sale of assets, shown below the operating profit line"], ans: 3, exp: "Non-operating income from investments, interest, dividend, and asset sales." },
  { id: 8049, sec: "8.4 P&L Analysis", q: "A manufacturer reports opening stock of raw materials Rs.100, purchases Rs.600 and closing stock Rs.150. The cost of raw materials consumed is:", opts: ["Rs.550", "Rs.650", "Rs.700", "Rs.850"], ans: 0, exp: "Raw materials consumed = Opening (100) + Purchases (600) - Closing (150) = Rs.550." },
  { id: 8050, sec: "8.4 P&L Analysis", q: "'Purchase of stock-in-trade' represents:", opts: ["raw materials consumed", "purchases of goods sold to customers without additional processing", "purchase of machinery", "shares purchased as investment"], ans: 1, exp: "Finished goods bought directly for resale without further processing." },
  { id: 8051, sec: "8.4 P&L Analysis", q: "The line 'changes in inventory of WIP and finished goods' represents:", opts: ["the cost of unsold raw materials only", "the depreciation on inventory", "the difference between opening and closing balance of work-in-progress and finished goods", "provision for doubtful debts"], ans: 2, exp: "Adjusts total production costs so that only goods sold during the year are charged to P&L." },
  { id: 8052, sec: "8.4 P&L Analysis", q: "Employee cost in the P&L may include:", opts: ["only cash salaries paid", "only bonus", "only retirement benefits paid in cash", "salaries, benefits, notional expenses on stock-based compensation, staff welfare and annual provision for retirement benefits"], ans: 3, exp: "Includes cash compensation, ESOP expenses, retirement provisions, and employee benefits." },
  { id: 8053, sec: "8.4 P&L Analysis", q: "Depreciation is best described as:", opts: ["a process of allocating the one-time expense on tangible assets and recovering it over their useful life", "the write-off of intangible assets", "a cash outflow each year", "the revaluation of assets upward"], ans: 0, exp: "Non-cash periodic cost allocation of tangible fixed assets over their useful economic life." },
  { id: 8054, sec: "8.4 P&L Analysis", q: "Per IndAS 16, the method of depreciation should take into account:", opts: ["only the purchase price", "the way the asset is used", "the tax rate", "the dividend policy"], ans: 1, exp: "Depreciation method must reflect the pattern in which the asset's future economic benefits are expected to be consumed." },
  { id: 8055, sec: "8.4 P&L Analysis", q: "Finance cost in the P&L includes:", opts: ["only dividend paid", "only interest earned", "interest, processing fee and amortisation of expenses incurred towards security issuance", "depreciation of assets"], ans: 2, exp: "Covers interest expense, borrowing fees, and ancillary costs of debt." },
  { id: 8056, sec: "8.4 P&L Analysis", q: "Exceptional / non-recurring items are:", opts: ["regular operating expenses", "recurring interest expenses", "tax deducted at source", "income or expenses that do not normally arise in the normal course of business, such as loss from natural calamities or one-time regulatory charges"], ans: 3, exp: "Unusual items shown separately to avoid distorting normal recurring operating trends." },
  { id: 8057, sec: "8.4 P&L Analysis", q: "The tax expense of an Indian company, as per the chapter, comprises:", opts: ["current tax, MAT and deferred tax", "current tax and wealth tax", "MAT and GST", "deferred tax and customs duty"], ans: 0, exp: "Total tax expense = Current Tax + Minimum Alternate Tax (MAT) impact + Deferred Tax." },
  { id: 8058, sec: "8.4 P&L Analysis", q: "Which statement about deferred tax is correct?", opts: ["It is a cash payment made to the government in the year", "It has no cash impact and arises from timing mismatch between tax authorities and accounting standards", "It is the same as MAT", "It arises only from exceptional items"], ans: 1, exp: "Deferred tax is a non-cash accounting adjustment for temporary timing differences between book profit and tax profit." },
  { id: 8059, sec: "8.4 P&L Analysis", q: "MAT paid by a company is, in theory, shown as an asset in the balance sheet because:", opts: ["it is refundable immediately", "it has no effect on profit", "it can be used as a credit against future tax", "it represents goodwill"], ans: 2, exp: "MAT credit entitlement is an asset because it can offset future regular tax liability." },
  { id: 8060, sec: "8.4 P&L Analysis", q: "Profit allocated to non-controlling interest in the P&L represents:", opts: ["dividend paid to the parent", "tax paid by the parent", "profit of associates", "profit of a subsidiary belonging to shareholders other than the parent"], ans: 3, exp: "Share of subsidiary's net profit belonging to outside minority owners." },
  { id: 8061, sec: "8.4 P&L Analysis", q: "Earnings per share (EPS) is calculated by dividing:", opts: ["net profit attributable to equity shareholders by the weighted average number of shares outstanding", "total revenue by closing shares", "EBITDA by number of employees", "PAT by net worth"], ans: 0, exp: "Basic EPS = PAT attributable to ordinary shareholders / Weighted average number of shares." },
  { id: 8062, sec: "8.4 P&L Analysis", q: "Diluted EPS is calculated assuming that:", opts: ["all shareholders sell their shares", "instruments potentially convertible into equity (in-the-money warrants, ESOPs, convertibles) are converted", "dividends are doubled", "no new shares are ever issued"], ans: 1, exp: "Diluted EPS assumes full conversion of dilutive securities (convertible debentures, ESOPs, options)." },
  { id: 8063, sec: "8.4 P&L Analysis", q: "For a loss-making company:", opts: ["diluted EPS is higher than basic EPS", "diluted EPS is zero", "diluted EPS and basic EPS are the same", "EPS cannot be computed"], ans: 2, exp: "Anti-dilutive effects are ignored; when net profit is negative, diluted EPS equals basic EPS." },
  { id: 8064, sec: "8.4 P&L Analysis", q: "Net profit attributable to equity shareholders is Rs.120 million and the weighted average number of shares outstanding is 40 million. EPS is:", opts: ["Rs.0.33", "Rs.30", "Rs.4.8", "Rs.3.0"], ans: 3, exp: "EPS = 120 / 40 = Rs.3.0 per share." },
  { id: 8065, sec: "8.4 P&L Analysis", q: "Which of the following is NOT an item of other comprehensive income per the chapter?", opts: ["Profit on sale of PPE", "Re-measurement gain/loss on defined benefit plans", "Gains/losses on translation of foreign operations", "Gain/loss on derivative contracts that effectively hedge risk"], ans: 0, exp: "Profit on sale of PPE goes directly to P&L (other income), not OCI." },
  { id: 8066, sec: "8.4 P&L Analysis", q: "In a 'multi-step' P&L, the first profit measure computed after total revenue less operating expenses is:", opts: ["PAT", "EBITDA", "EBIT", "Profit before tax"], ans: 1, exp: "Multi-step formats compute EBITDA first, before deducting depreciation and interest." },
  { id: 8067, sec: "8.4 P&L Analysis", q: "Gross profit is calculated by:", opts: ["reducing tax from EBIT", "adding depreciation to PAT", "reducing the cost of goods sold from revenue", "deducting interest from EBITDA"], ans: 2, exp: "Gross Profit = Revenue - Cost of Goods Sold (COGS)." },
  { id: 8068, sec: "8.4 P&L Analysis", q: "Why is EBITDA considered useful for comparing two firms?", opts: ["It includes all taxes paid", "It is always higher than revenue", "It includes interest income and extra-ordinary gains", "It is not affected by capital structure and infrastructure choices or depreciation methodology"], ans: 3, exp: "EBITDA strips out differences in debt leverage, asset age/depreciation policies, and tax rates." },
  { id: 8069, sec: "8.4 P&L Analysis", q: "EBIT (operating profit) is a useful metric to measure:", opts: ["the ability of the firm to meet annual interest or financial expenses", "the amount of tax saved", "the number of shares outstanding", "the cash balance at the year end"], ans: 0, exp: "EBIT is the numerator in the interest coverage ratio (EBIT / Interest Expense)." },
  { id: 8070, sec: "8.4 P&L Analysis", q: "Airtel FY2019: EBITDA Rs.2,61,101 mn; depreciation & amortisation Rs.2,13,475 mn. EBIT is:", opts: ["Rs.4,74,576 mn", "Rs.47,626 mn", "Rs.2,13,475 mn", "Rs.1,10,848 mn"], ans: 1, exp: "EBIT = EBITDA - D&A = 2,61,101 - 2,13,475 = Rs.47,626 million." },
  { id: 8071, sec: "8.4 P&L Analysis", q: "A company reports PAT of Rs.500, including an exceptional gain of Rs.100 taxed at 30%. Adjusted PAT (excluding the exceptional item) is:", opts: ["Rs.400", "Rs.470", "Rs.430", "Rs.370"], ans: 2, exp: "After-tax exceptional gain = 100 * (1 - 0.30) = 70. Adjusted PAT = 500 - 70 = Rs.430." },
  { id: 8072, sec: "8.4 P&L Analysis", q: "Why did the chapter call Airtel's FY2019 effective tax rate 'not meaningful'?", opts: ["The company paid no taxes", "The tax rate was fixed by SEBI", "Tax is not shown in the P&L", "The company paid huge taxes despite reporting losses"], ans: 3, exp: "Due to exceptional regulatory charges and deferred tax reversals, Airtel showed heavy tax expense despite pre-tax losses." },
  { id: 8073, sec: "8.5 Statement of Changes in Equity", q: "The statement of changes in shareholder's equity shows:", opts: ["the impact of various types of transactions on the various components of shareholder's equity", "only dividends paid", "cash flows from operations", "a list of contingent liabilities"], ans: 0, exp: "Details share capital movements, retained earnings, reserves, OCI, and dividend distributions." },
  { id: 8074, sec: "8.6 Cash Flow Statement", q: "Generating cash is critical to a firm's long-term survival because P&L and balance sheet are prepared on accrual basis, which means:", opts: ["income is recognised only when cash is received", "income is recognised when earned rather than received and expenses when incurred rather than paid", "expenses are recognised only when paid", "there is no difference between profit and cash flow"], ans: 1, exp: "Accrual basis records revenue when earned and costs when incurred, irrespective of actual cash movement." },
  { id: 8075, sec: "8.6 Cash Flow Statement", q: "A business buys goods for Rs.80,000 in cash and sells them for Rs.100,000 on credit; the customer has not paid. Which is correct?", opts: ["P&L shows a loss of Rs.80,000", "Cash flow is positive by Rs.20,000", "P&L shows profit of Rs.20,000 but the business has no cash from the sale", "There is no profit or cash impact"], ans: 2, exp: "P&L shows profit of Rs.20,000 (100k - 80k), but net cash flow is -Rs.80,000 because receivable is uncollected." },
  { id: 8076, sec: "8.6 Cash Flow Statement", q: "Which section of the cash flow statement shows the amount of funds a company borrowed during the preceding year?", opts: ["Cash flows from operating activities", "Cash flows from investing activities", "Cash flows from net operations", "Cash flows from financing activities"], ans: 3, exp: "Financing activities record proceeds from debt issuance, equity issuance, and repayments." },
  { id: 8077, sec: "8.6 Cash Flow Statement", q: "Buying fixed assets results in:", opts: ["a negative investing cash flow", "a positive investing cash flow", "a positive financing cash flow", "a positive operating cash flow"], ans: 0, exp: "Capital expenditure on PPE is an outflow (negative) under Cash Flows from Investing Activities." },
  { id: 8078, sec: "8.6 Cash Flow Statement", q: "To arrive at operating cash flow from net profit, a company:", opts: ["deducts depreciation again", "adds back non-cash expenses such as depreciation and amortisation and adjusts for changes in receivables and payables", "ignores working capital changes", "adds back dividend paid"], ans: 1, exp: "Net profit is adjusted for non-cash items (D&A) and operating working capital changes." },
  { id: 8079, sec: "8.6 Cash Flow Statement", q: "A business continuously reports negative operating cash flows for several years. The chapter's view is that:", opts: ["it is normal for any growing business and requires no concern", "it only indicates high depreciation", "it is an alarming signal; the business needs continuous infusion of borrowings or equity and may die if lenders/investors refuse to fund it", "it proves that profits are high"], ans: 2, exp: "Persistent negative OCF is a severe warning sign of cash burn that requires perpetual external financing." },
  { id: 8080, sec: "8.6 Cash Flow Statement", q: "A business that is expanding, with negative investing cash flows, would typically finance them through:", opts: ["negative operating cash flows only", "reducing share capital", "revaluing its assets upward", "positive operating cash flows, accumulated cash, or positive financing cash flows"], ans: 3, exp: "Capex is funded by operating cash surpluses, cash reserves, or fresh debt/equity capital." },
  { id: 8081, sec: "8.6 Cash Flow Statement", q: "Which of the following are points to be kept in mind when reading cash flows? I. Net cash flow could be deceptive. II. Operating, investing and financing streams must be analysed independently. III. Focus on sustainable and recurring cash flows. IV. Non-recurring items need not be adjusted.", opts: ["II and IV only", "I, II and III only", "I, II, III and IV", "I and IV only"], ans: 1, exp: "Statement IV is incorrect because non-recurring and extraordinary cash flows must always be adjusted." },
  { id: 8082, sec: "8.7 Contingent Liabilities & Off-Balance Sheet", q: "Which of the following is a contingent liability?", opts: ["Salaries payable next month", "A liability that may arise depending on the outcome of a pending lawsuit", "Long-term borrowings from a bank", "Trade payables"], ans: 1, exp: "Pending lawsuits depend on uncertain future court verdicts, making them contingent liabilities." },
  { id: 8083, sec: "8.7 Contingent Liabilities & Off-Balance Sheet", q: "Prominent examples of contingent liabilities listed in the chapter include all of the following EXCEPT:", opts: ["Outstanding lawsuits", "Disputes with tax authorities", "Trade payables to regular suppliers", "Bank guarantees provided"], ans: 2, exp: "Trade payables are recognized current liabilities on the face of the balance sheet." },
  { id: 8084, sec: "8.7 Contingent Liabilities & Off-Balance Sheet", q: "If a company is continuously changing its accounting policies, the analyst should:", opts: ["treat it as a sign of efficiency", "ignore it, since policies are not relevant to analysis", "assume profits are understated", "treat it as a reason for suspicion and scrutinise whether the company is manipulating the financials"], ans: 3, exp: "Frequent changes in accounting policies can be used to manage earnings and require deep scrutiny." },
  { id: 8085, sec: "8.7 Contingent Liabilities & Off-Balance Sheet", q: "Which of the following is an off-balance sheet item as per the chapter?", opts: ["Operating lease", "Loans taken by the company", "Share capital", "Trade receivables"], ans: 0, exp: "Operating commitments, contingent liabilities, and unrecognised lease arrangements represent off-balance sheet exposures." },
  { id: 8086, sec: "8.7 Contingent Liabilities & Off-Balance Sheet", q: "To judge the seriousness of contingent liabilities, an analyst should:", opts: ["rely on the management's assurance that nothing will be paid", "compare their quantum with the size of the P&L and balance sheet", "ignore them if the company is profitable", "add them to equity"], ans: 1, exp: "Compare the magnitude of contingent claims against net worth and annual profits to assess materiality." },
  { id: 8087, sec: "8.8 Long-Term Value Creation", q: "According to the chapter, a company that creates value over the long term is one that:", opts: ["reports large one-off gains every year", "changes its accounting period frequently", "consistently grows sales, profits, net worth and margins while reducing debt and improving RONW", "distributes all profits as dividends"], ans: 2, exp: "Sustainable value creation requires steady growth in revenues, margins, net worth, and returns on capital with disciplined leverage." },
  { id: 8088, sec: "8.9 Audit Quality & Opinions", q: "Who is responsible for preparing the accounts, and what do auditors do?", opts: ["Auditors prepare; management verifies", "Both are equally responsible for preparation", "SEBI prepares; auditors file", "Management prepares; auditors verify that they present a true and fair view"], ans: 3, exp: "Management is responsible for preparation; independent statutory auditors verify that they present a true and fair view." },
  { id: 8089, sec: "8.9 Audit Quality & Opinions", q: "Why can auditors NOT vouch for the accuracy of accounting?", opts: ["The amount of transactions is so large that all cannot be checked for completeness and accuracy", "Auditors are not permitted to see transactions", "Companies do not keep records", "Accounting standards are optional"], ans: 0, exp: "Auditing relies on sample testing and internal controls evaluation; checking every single entry is impossible." },
  { id: 8090, sec: "8.9 Audit Quality & Opinions", q: "Arrange the audit approach described in the chapter in the correct sequence: P. Check that accounting standards are followed; Q. Verify company has adequate control systems; R. Check control systems were properly implemented.", opts: ["P, Q, R", "R, Q, P", "Q, P, R", "Q, R, P"], ans: 3, exp: "1. Evaluate control system design (Q) -> 2. Verify controls are operating effectively (R) -> 3. Substantive testing against accounting standards (P)." },
  { id: 8091, sec: "8.9 Audit Quality & Opinions", q: "An auditor issues a report stating that he was unable to verify any part of the financials due to non-availability of information. This is a:", opts: ["clean report", "qualified report", "disclaimer", "adverse comparative"], ans: 2, exp: "A disclaimer of opinion is issued when auditors cannot obtain sufficient audit evidence to form any opinion." },
  { id: 8092, sec: "8.9 Audit Quality & Opinions", q: "An auditor disagrees with the accounting policy followed by the company and believes part of the financial statements does not reflect a true and fair view. The report is:", opts: ["clean", "disclaimer", "neutral", "qualified"], ans: 3, exp: "A qualified report indicates disagreement with accounting treatment or non-compliance while overall statements are mostly reliable." },
  { id: 8093, sec: "8.9 Audit Quality & Opinions", q: "In a clean audit report, which part may vary across companies?", opts: ["Certain information presented in line with the Companies (Auditor's Report) Order", "The auditor's opinion on true and fair view", "The year of incorporation", "The ratios computed"], ans: 0, exp: "CARO reporting items detail specific matters like inventory verification, statutory dues, and loan defaults." },
  { id: 8094, sec: "8.10 Ratio Analysis Basics", q: "Ratio analysis involves:", opts: ["adding all line items together", "expressing one financial statement line item as a percentage or multiple of another related line item", "comparing unrelated numbers", "using only non-financial data"], ans: 1, exp: "Evaluating proportional relationships between related financial line items." },
  { id: 8095, sec: "8.10 Ratio Analysis Basics", q: "The three purposes of ratio analysis described in the chapter are:", opts: ["descriptive, regulatory and tax", "accounting, audit and legal", "descriptive, diagnostic and predictive", "historical, comparative and promotional"], ans: 2, exp: "Descriptive (summarizes performance), Diagnostic (identifies underlying causes), Predictive (forecasts future trajectory)." },
  { id: 8096, sec: "8.10 Ratio Analysis Basics", q: "Bharti Airtel's revenue declined about 2% in FY2019 but EBITDA declined about 14%. Ratio analysis showed the main reason was:", opts: ["employee benefit expenses rising sharply", "licence fee rising sharply", "sales and marketing rising sharply", "network operating expense rose significantly as a percentage of revenue (23.8% to 27.6%)"], ans: 3, exp: "Network operating expenses rose from 23.8% to 27.6% of revenue, eroding EBITDA margins." },
  { id: 8097, sec: "8.10 Ratio Analysis Basics", q: "The observation that network operating expense rose as a percentage of sales when sales fell suggests network operating expense is:", opts: ["largely fixed in nature and independent of sales", "fully variable with sales", "a non-cash expense", "an exceptional item"], ans: 0, exp: "Cell tower rentals and network operating costs are largely fixed costs that do not decrease when sales dip." },
  { id: 8098, sec: "8.11 Financial Ratios", q: "The only requirement while using ratios, as the chapter highlights, is that:", opts: ["both numbers must be in the same currency unit only", "the two numbers being compared should be related in some way", "both must come from the balance sheet", "the ratio must exceed 1"], ans: 1, exp: "A meaningful ratio requires an economic or operational linkage between the numerator and denominator." },
  { id: 8099, sec: "8.11 Financial Ratios", q: "Which of the following correctly states the EBITDA margin?", opts: ["EBIT / Capital employed", "PAT / Net worth", "EBITDA / Net sales", "EBITDA / Total assets"], ans: 2, exp: "EBITDA Margin = (EBITDA / Net Sales) * 100." },
  { id: 8100, sec: "8.11 Financial Ratios", q: "Airtel's EBITDA margin was 36.6% in FY2018 and 32.2% in FY2019. The decline is approximately:", opts: ["44 basis points", "4,400 basis points", "4.4 basis points", "440 basis points"], ans: 3, exp: "36.6% - 32.2% = 4.4% = 440 basis points (1% = 100 bps)." },
  { id: 8101, sec: "8.11 Financial Ratios", q: "A very high level of profitability in an industry is:", opts: ["unlikely to be sustained over a long period as new entrants and competition lower it", "guaranteed to last for decades", "caused only by high debt", "always due to lower depreciation"], ans: 0, exp: "Abnormal economic profits attract new capital and competitors, driving down margins over time." },
  { id: 8102, sec: "8.11 Financial Ratios", q: "EBITDA is Rs.250 and net sales are Rs.1,000. Depreciation is Rs.100 and PAT is Rs.60. The EBITDA margin and PAT margin are:", opts: ["15% and 6%", "25% and 6%", "25% and 24%", "10% and 6%"], ans: 1, exp: "EBITDA Margin = 250 / 1000 = 25%; PAT Margin = 60 / 1000 = 6%." },
  { id: 8103, sec: "8.11 Financial Ratios", q: "NOPAT (Net Operating Profit After Tax) is calculated as:", opts: ["EBITDA x (1 - tax rate)", "PAT x (1 - tax rate)", "EBIT x (1 - tax rate)", "EBIT / (1 - tax rate)"], ans: 2, exp: "NOPAT = EBIT * (1 - Tax Rate)." },
  { id: 8104, sec: "8.11 Financial Ratios", q: "Return on Equity (ROE) is calculated as:", opts: ["EBIT / Capital employed", "PAT / Net sales", "EBITDA / Net-worth", "PAT / Net-worth"], ans: 3, exp: "ROE (Return on Net Worth) = PAT / Net Worth." },
  { id: 8105, sec: "8.11 Financial Ratios", q: "Net-worth is calculated as:", opts: ["equity share capital (at face value) plus reserves and surplus", "equity share capital at market value plus debt", "total assets minus current assets", "reserves minus share capital"], ans: 0, exp: "Net Worth = Equity Share Capital + Reserves and Surplus." },
  { id: 8106, sec: "8.11 Financial Ratios", q: "Why does the chapter recommend using average net-worth rather than year-end net-worth in ROE?", opts: ["Because average values are always higher", "Sales and profit are for a period, whereas net worth is as at a particular date", "Because year-end values are not disclosed", "Because SEBI mandates it"], ans: 1, exp: "P&L items accrue over the entire year, so pairing them with average balance sheet figures is methodologically sound." },
  { id: 8107, sec: "8.11 Financial Ratios", q: "PAT is Rs.240. Net worth at the start of the year is Rs.900 and at the end Rs.1,100. ROE using average net worth is:", opts: ["21.8%", "26.7%", "24%", "12%"], ans: 2, exp: "Average Net Worth = (900 + 1100)/2 = 1,000. ROE = 240 / 1,000 = 24%." },
  { id: 8108, sec: "8.11 Financial Ratios", q: "Return on Capital Employed (ROCE) is calculated as:", opts: ["PAT / Capital employed", "EBITDA / Net worth", "EBIT / Net sales", "EBIT / Capital employed"], ans: 3, exp: "ROCE = EBIT / Total Capital Employed." },
  { id: 8109, sec: "8.11 Financial Ratios", q: "Capital employed can be calculated as:", opts: ["total assets minus non-interest-bearing current liabilities, or total book value of equity plus total book value of debt", "total assets plus current liabilities", "equity minus debt", "current assets minus inventory"], ans: 0, exp: "Capital Employed = Total Assets - Non-interest-bearing Current Liabilities = Equity + Total Debt." },
  { id: 8110, sec: "8.11 Financial Ratios", q: "EBIT is Rs.300. Capital employed at start and end of year are Rs.1,400 and Rs.1,600. If tax rate is 30%, post-tax ROCE is:", opts: ["20%", "14%", "18.75%", "10%"], ans: 1, exp: "Average Capital Employed = 1,500. Pre-tax ROCE = 300 / 1,500 = 20%. Post-tax = 20% * (1 - 0.30) = 14%." },
  { id: 8111, sec: "8.11 Financial Ratios", q: "Which statement about ROCE is correct?", opts: ["It is a post-tax measure by definition", "It uses PAT in the numerator", "It is a pre-tax measure; analysts may multiply it by (1- tax rate) to arrive at a post-tax rate of return", "It excludes debt from capital employed"], ans: 2, exp: "ROCE is inherently pre-tax since EBIT is pre-tax; analysts adjust by (1 - t) for post-tax comparisons." },
  { id: 8112, sec: "8.11 Financial Ratios", q: "Airtel FY2019 capital employed: Equity Rs.8,49,480 mn, LT debt Rs.8,72,454 mn, ST debt Rs.3,10,097 mn, current maturities of LT debt Rs.71,732 mn. Total capital is:", opts: ["Rs.17,22,019 mn", "Rs.12,87,036 mn", "Rs.18,96,818 mn", "Rs.21,03,763 mn"], ans: 3, exp: "8,49,480 + 8,72,454 + 3,10,097 + 71,732 = Rs.21,03,763 million." },
  { id: 8113, sec: "8.11 Financial Ratios", q: "Debt/Equity (D/E) ratio is calculated as:", opts: ["total adjusted debt / net-worth", "net-worth / total debt", "EBIT / interest expense", "current assets / current liabilities"], ans: 0, exp: "Debt to Equity = Total Interest-Bearing Debt / Net Worth." },
  { id: 8114, sec: "8.11 Financial Ratios", q: "On a most conservative basis, which D/E ratio would be considered the benchmark?", opts: ["3 or more", "1 or less", "5", "10"], ans: 1, exp: "Conservative credit principles benchmark D/E <= 1.0." },
  { id: 8115, sec: "8.11 Financial Ratios", q: "In the D/E ratio, adjusted debt usually includes:", opts: ["only long-term bank loans", "only bonds", "all interest-bearing liabilities (short or long term), pension deficits and convertibles", "trade payables"], ans: 2, exp: "Captures all short- and long-term interest liabilities, capitalized lease debts, and pension obligations." },
  { id: 8116, sec: "8.11 Financial Ratios", q: "Total adjusted debt is Rs.1,800 and net-worth is Rs.1,200. D/E is:", opts: ["0.67x", "3.0x", "1.0x", "1.5x"], ans: 3, exp: "D/E = 1,800 / 1,200 = 1.5x." },
  { id: 8117, sec: "8.11 Financial Ratios", q: "Interest coverage ratio is:", opts: ["EBIT / interest expense", "EBITDA / principal repayment", "PAT / interest expense", "interest expense / EBIT"], ans: 0, exp: "Interest Coverage Ratio = EBIT / Interest Expense." },
  { id: 8118, sec: "8.11 Financial Ratios", q: "A company has EBIT of Rs.90 and interest expense of Rs.30. If EBIT falls to Rs.20, the interest coverage ratio will be:", opts: ["greater than 1 but lower than before", "less than 1, indicating earnings are below interest obligations", "unchanged", "cannot be computed"], ans: 1, exp: "Coverage drops from 90/30 = 3x to 20/30 = 0.67x (<1), meaning operating earnings do not cover interest." },
  { id: 8119, sec: "8.11 Financial Ratios", q: "The current ratio is calculated as:", opts: ["current liabilities / current assets", "(current assets - inventories) / current liabilities", "current assets / current liabilities", "cash / total assets"], ans: 2, exp: "Current Ratio = Current Assets / Current Liabilities." },
  { id: 8120, sec: "8.11 Financial Ratios", q: "Bharti Airtel FY2019: current assets Rs.3,29,057 mn and current liabilities Rs.9,30,549 mn. The current ratio is approximately:", opts: ["2.83", "0.65", "1.52", "0.35"], ans: 3, exp: "Current ratio = 3,29,057 / 9,30,549 = 0.35x." },
  { id: 8121, sec: "8.11 Financial Ratios", q: "A company takes cash on sales and makes payments to suppliers on credit, resulting in a current ratio below 1. This situation is:", opts: ["not a red flag; it can be a good situation as the working is funded by customers", "always a sign of imminent bankruptcy", "a sign of poor inventory management", "a violation of IndAS"], ans: 0, exp: "In retail/telecom, negative working capital funded by customer advance cash is often a sign of market strength." },
  { id: 8122, sec: "8.11 Financial Ratios", q: "The quick ratio differs from the current ratio in that it:", opts: ["includes non-current assets", "excludes inventories from current assets", "uses only cash in the numerator", "excludes receivables"], ans: 1, exp: "Quick Ratio = (Current Assets - Inventories) / Current Liabilities." },
  { id: 8123, sec: "8.11 Financial Ratios", q: "Current assets are Rs.600, inventory is Rs.200 and current liabilities are Rs.400. Current ratio and quick ratio are:", opts: ["1.5 and 1.5", "1.0 and 1.5", "1.5 and 1.0", "3.0 and 2.0"], ans: 2, exp: "Current Ratio = 600 / 400 = 1.5; Quick Ratio = (600 - 200) / 400 = 1.0." },
  { id: 8124, sec: "8.11 Financial Ratios", q: "A high inventory of finished goods may indicate that:", opts: ["production planning is poor", "suppliers give long credit", "the company has high bargaining power", "sales are slowing down"], ans: 3, exp: "Finished goods stacking up indicates sluggish demand or market slowdown." },
  { id: 8125, sec: "8.11 Financial Ratios", q: "Accounts receivable turnover is calculated as:", opts: ["revenue / average accounts receivable", "purchases / accounts payable", "sales / inventory", "net sales / total assets"], ans: 0, exp: "Receivables Turnover = Net Credit Sales (or Revenue) / Average Accounts Receivable." },
  { id: 8126, sec: "8.11 Financial Ratios", q: "Revenue is Rs.1,200. Accounts receivable were Rs.100 at the start and Rs.140 at the end. Accounts receivable turnover is:", opts: ["8.57 times", "10 times", "12 times", "1.2 times"], ans: 1, exp: "Average receivables = (100 + 140)/2 = 120. Turnover = 1,200 / 120 = 10 times." },
  { id: 8127, sec: "8.11 Financial Ratios", q: "If accounts payable is high, the accounts payable turnover ratio will be:", opts: ["high, which is always good", "zero", "low, which may mean long credit periods from suppliers; it could reflect strong bargaining power or inability to pay", "unaffected"], ans: 2, exp: "Low payable turnover means extended payment periods, reflecting either supplier bargaining power or cash strain." },
  { id: 8128, sec: "8.11 Financial Ratios", q: "Asset turnover ratio is:", opts: ["total assets / net sales", "PAT / total assets", "EBIT / total assets", "net sales / total assets"], ans: 3, exp: "Asset Turnover = Net Sales / Average Total Assets." },
  { id: 8129, sec: "8.11 Financial Ratios", q: "Inventory turnover is typically:", opts: ["high for FMCG companies and low for capital goods companies", "low for FMCG and high for capital goods", "equal across all industries", "meaningless for manufacturing firms"], ans: 0, exp: "FMCG products sell rapidly (high turnover), whereas capital goods take months to build and sell." },
  { id: 8130, sec: "8.12 DuPont Analysis", q: "Dupont analysis decomposes ROE into:", opts: ["EBITDA margin, ROCE and D/E", "net profit margin, asset turnover and leverage (equity multiplier)", "current ratio, quick ratio and interest coverage", "profit margin, dividend yield and EPS"], ans: 1, exp: "ROE = Net Profit Margin (Profitability) * Asset Turnover (Efficiency) * Financial Leverage Multiplier." },
  { id: 8131, sec: "8.12 DuPont Analysis", q: "A company has net profit margin of 8%, asset turnover of 1.5x and assets-to-equity of 2x. Its ROE is:", opts: ["12%", "16%", "24%", "9.5%"], ans: 2, exp: "ROE = 0.08 * 1.5 * 2 = 0.24 = 24%." },
  { id: 8132, sec: "8.12 DuPont Analysis", q: "In the chapter's example, HighLevCo has ROE of 92.3% and LowLevCo 52.4%. Dupont analysis reveals that:", opts: ["HighLevCo has better margin and turnover", "both companies have equal leverage", "LowLevCo has higher leverage but lower margin", "LowLevCo has marginally better asset turnover and better margin; its lower ROE is only due to low leverage"], ans: 3, exp: "DuPont exposes that HighLevCo's inflated ROE is driven purely by extreme financial debt leverage." },
  { id: 8133, sec: "8.12 DuPont Analysis", q: "If ROE rises solely because of higher leverage, the chapter's view is that:", opts: ["it need not be a reason to cheer, as higher leverage brings higher risk", "it is always a reason to cheer", "it shows higher asset efficiency", "it shows higher profit margin"], ans: 0, exp: "Boosting ROE with excessive debt magnifies financial fragility rather than business strength." },
  { id: 8134, sec: "8.12 DuPont Analysis", q: "Which Dupont component represents operating efficiency in use of assets?", opts: ["Net profit margin", "Asset turnover (Sales / Assets)", "Assets / Equity", "Profit / Equity"], ans: 1, exp: "Sales / Assets gauges the intensity and efficiency with which assets generate revenues." },
  { id: 8135, sec: "8.13 Forecasting", q: "While forecasting based on historical ratios, analysts must keep in mind that:", opts: ["past behaviour is always repeated", "forecasts are legally binding", "past behaviour may not be a fair representation of the future and judgement adjustments are needed", "ratios cannot be computed for the future"], ans: 2, exp: "Structural changes, new technology, and competitive shifts mean past trends cannot simply be extrapolated." },
  { id: 8136, sec: "8.13 Forecasting", q: "The Suzlon example in the chapter illustrates that:", opts: ["wind turbine companies never face competition", "ratio analysis is useless", "only stand-alone statements matter", "the future of a business can be significantly different from its past"], ans: 3, exp: "Suzlon dominated until domestic and global competitors entered, drastically reshaping its financial trajectory." },
  { id: 8137, sec: "8.14 Peer Comparison", q: "Peer comparison is useful because:", opts: ["it shows a company's competitive position relative to others in the industry", "it removes the need for financial analysis", "it applies only to unlisted companies", "it is required by Schedule III"], ans: 0, exp: "Benchmarking against peers highlights competitive advantages, superior margins, or cost inefficiencies." },
  { id: 8138, sec: "8.15 Capital Actions & Corporate Actions", q: "Which of the following is NOT a model of issuing equity shares mentioned in the chapter?", opts: ["Rights issue", "Share buy-back", "Public issue (IPO/FPO)", "Private placement"], ans: 1, exp: "Share buy-back retires equity shares rather than issuing them." },
  { id: 8139, sec: "8.15 Capital Actions & Corporate Actions", q: "A rights issue causes dilution:", opts: ["to all shareholders equally", "only to promoters", "only to shareholders who do not exercise their rights", "never, under any circumstance"], ans: 2, exp: "Shareholders who renounce or do not exercise their rights see their ownership stake diluted." },
  { id: 8140, sec: "8.15 Capital Actions & Corporate Actions", q: "Which statement about preferential allotment is correct?", opts: ["It always benefits existing shareholders", "It is never priced at a premium", "Regulators do not set any minimum price", "It increases the stake of the preferential investor and reduces that of others; premium pricing makes it value accretive to minority shareholders"], ans: 3, exp: "Preferential issues allocate equity to specific strategic investors; premium pricing can be value-accretive." },
  { id: 8141, sec: "8.15 Capital Actions & Corporate Actions", q: "A qualified institutional placement (QIP), though it dilutes ownership, is likely to point towards:", opts: ["confidence among institutional investors in the company's fundamentals", "poor governance", "a debt covenant breach", "a reduction in share capital"], ans: 0, exp: "QIP institutional uptake reflects high institutional confidence in the corporate outlook." },
  { id: 8142, sec: "8.15 Capital Actions & Corporate Actions", q: "Companies that finance their growth through strong internal accruals:", opts: ["always dilute equity heavily", "create very little concern for investors regarding equity dilution", "must issue only preference shares", "cannot pay dividends"], ans: 1, exp: "Self-financing via retained profits avoids EPS dilution and debt burden." },
  { id: 8143, sec: "8.15 Capital Actions & Corporate Actions", q: "During the growth phase of a company, as per the chapter:", opts: ["companies pay maximum dividends", "dividends are mandatory by law", "companies are likely to pay less or no dividend as they need funds to fuel growth", "buy-backs are prohibited"], ans: 2, exp: "Growth firms reinvest their profits into high-return expansion projects instead of distributing dividends." },
  { id: 8144, sec: "8.15 Capital Actions & Corporate Actions", q: "Which companies are cited as examples offering predictable interim dividends in matured defensive industries?", opts: ["Bharti Airtel and Suzlon", "Toyota and Kingfisher", "Reliance and Jio Platforms", "Colgate Palmolive and Britannia"], ans: 3, exp: "Colgate and Britannia operate in defensive FMCG niches with steady cash generation and high payouts." },
  { id: 8145, sec: "8.15 Capital Actions & Corporate Actions", q: "Companies may prefer a share buy-back over dividends when:", opts: ["there is favourable tax treatment for investors and/or the company; it also lets investors choose between encashing the offer or increasing stake", "dividends are prohibited by SEBI", "the company wants to issue more shares", "the company has negative net worth"], ans: 0, exp: "Buy-backs offer tax advantages and let shareholders choose whether to participate or stay invested." },
  { id: 8146, sec: "8.15 Capital Actions & Corporate Actions", q: "A company with good performance begins to retain more profit than usual. The chapter's interpretation is that this:", opts: ["definitely indicates poor performance", "may indicate a major investment plan, or that the company expects a challenging environment ahead", "definitely indicates a major acquisition", "has no informational value"], ans: 1, exp: "Higher profit retention signals large pending capex/acquisitions or preparation for turbulent conditions." },
  { id: 8147, sec: "8.15 Capital Actions & Corporate Actions", q: "According to the Peter Lynch quote in the chapter, if insiders are buying:", opts: ["it is a sign of insider trading violations", "the company is likely to fail", "there can be only one reason - the company is likely to make huge profits in the future", "it carries no signal"], ans: 2, exp: "Insiders may sell shares for personal expenses, but they only buy because they believe the price will go up." },
  { id: 8148, sec: "8.15 Capital Actions & Corporate Actions", q: "Corporate actions mentioned in the chapter that affect share price include:", opts: ["audits, qualifications and disclaimers", "EBITDA, EBIT and PAT", "current, quick and cash ratios", "dividends, bonuses, splits and rights issues"], ans: 3, exp: "Dividends, bonus shares, stock splits, and rights offerings directly adjust share counts and market prices." },
  { id: 8149, sec: "8.15 Capital Actions & Corporate Actions", q: "Why are owners/promoters' transactions in the company's shares of interest to an analyst?", opts: ["owners are closest to the business and have the most information about its nuances", "they are always below market price", "they are not governed by any regulation", "they replace the need for financial statements"], ans: 0, exp: "Promoter buying and selling is a key barometer of internal management confidence." },
  { id: 8150, sec: "Sample Questions", q: "Which of the following items are found in an income statement?", opts: ["Change in accounts receivables", "Changes in inventory of finished goods and work in progress", "Changes in long term debt", "None of the above"], ans: 1, exp: "'Changes in inventories of finished goods and work-in-progress' is a standard line item in the P&L statement." },
  { id: 8151, sec: "Sample Questions", q: "Which of the following measures the ability of the company to satisfy its short-term obligations as and when they come due?", opts: ["Return on equity", "Return on capital employed", "Current ratio", "Inventory turnover ratio"], ans: 2, exp: "Current ratio measures short-term liquidity and ability to satisfy immediate current obligations." },
  { id: 8152, sec: "Sample Questions", q: "Price to earnings ratio of a business is 10, price to book value ratio is 5, book value per share is Rs.15 and shares outstanding is 10,000. What is the return on equity?", opts: ["25%", "75%", "20%", "50%"], ans: 3, exp: "ROE = (P/B) / (P/E) = 5 / 10 = 50%. Alternatively: Price = 5 * 15 = 75; EPS = 75 / 10 = 7.5; ROE = 7.5 / 15 = 50%." }
];
